mapper.select:
SELECT * FROM agent_conversation_turn
WHERE tenant_id = #{tenantId} AND conversation_id = #{conversationId} AND id = #{id}
FOR UPDATE

SELECT q.* FROM agent_conversation_turn q
WHERE q.direction = 'IN' AND q.status = 'QUEUED' AND q.id > #{afterId}
  AND NOT EXISTS (SELECT 1 FROM agent_conversation_turn p
    WHERE p.tenant_id = q.tenant_id AND p.conversation_id = q.conversation_id
      AND p.direction = 'IN' AND p.status = 'PROCESSING')
ORDER BY q.id ASC LIMIT #{limit}

SELECT 
FROM agent_conversation_turn t
JOIN agent_conversation c ON c.id = t.conversation_id AND c.tenant_id = t.tenant_id
WHERE t.tenant_id = #{tenantId}
  AND c.tenant_id = #{tenantId}
  AND c.executor_id = #{executorId}
  AND t.direction = 'IN'
  AND t.status = 'PROCESSING'
  AND (t.last_dispatch_at <= #{cutoff}
    OR (t.last_dispatch_at IS NULL AND t.gmt_create <= #{cutoff}))
ORDER BY COALESCE(t.last_dispatch_at, t.gmt_create) ASC, t.id ASC
LIMIT #{limit}

SELECT * FROM agent_conversation_turn
WHERE direction = 'IN' AND status = 'PROCESSING' AND id > #{afterId}
  AND (last_dispatch_at <= #{cutoff} OR (last_dispatch_at IS NULL AND gmt_create <= #{cutoff}))
ORDER BY id ASC LIMIT #{limit}

mapper.update:
UPDATE agent_conversation_turn
SET status = #{status}, error = LEFT(#{error}, 1024)
WHERE tenant_id = #{tenantId} AND id = #{id}

UPDATE agent_conversation_turn SET status = #{status}, error = LEFT(#{error}, 1024)
WHERE tenant_id = #{tenantId} AND conversation_id = #{conversationId} AND id = #{id}
  AND direction = 'IN' AND status = 'PROCESSING' AND dispatch_attempt = #{dispatchAttempt}

UPDATE agent_conversation_turn
SET status = #{status}, error = LEFT(#{error}, 1024)
WHERE tenant_id = #{tenantId}
  AND conversation_id = #{conversationId}
  AND id = #{id}
  AND direction = 'IN'
  AND status = 'PROCESSING'

UPDATE agent_conversation_turn
SET status = #{status}, error = LEFT(#{error}, 1024),
    source_context = CASE WHEN source_context IS NULL THEN #{sourceContext} ELSE source_context END
WHERE tenant_id = #{tenantId}
  AND conversation_id = #{conversationId}
  AND id = #{id}
  AND direction = 'IN'
  AND status = 'PROCESSING'

UPDATE agent_conversation_turn
SET status = #{toStatus}, error = LEFT(#{error}, 1024)
WHERE tenant_id = #{tenantId} AND id = #{id} AND status = #{fromStatus}

UPDATE agent_conversation_turn SET source_context = #{sourceContext}
WHERE tenant_id = #{tenantId} AND id = #{id} AND direction = 'IN' AND status = 'PROCESSING'
  AND (source_context = #{previousContext}
       OR (source_context IS NULL AND #{previousContext} IS NULL))

UPDATE agent_conversation_turn
SET last_dispatch_at = NOW(),
    dispatch_attempt = dispatch_attempt + 1
WHERE tenant_id = #{tenantId}
  AND conversation_id = #{conversationId}
  AND id = #{id}
  AND direction = 'IN'
  AND status = 'PROCESSING'

UPDATE agent_conversation_turn
SET last_dispatch_at = NOW(),
    dispatch_attempt = dispatch_attempt + 1
WHERE tenant_id = #{tenantId}
  AND conversation_id = #{conversationId}
  AND id = #{id}
  AND direction = 'IN'
  AND status = 'PROCESSING'
  AND (last_dispatch_at <= #{cutoff}
    OR (last_dispatch_at IS NULL AND gmt_create <= #{cutoff}))

