mapper.update:
UPDATE agent_conversation_turn
SET delivery_status = 'SENDING',
    delivery_attempt = delivery_attempt + 1,
    delivery_available_at = #{leaseUntil}
WHERE id = #{id}
  AND direction = 'OUT'
  AND delivery_status = 'SENDING'
  AND delivery_available_at IS NOT NULL
  AND delivery_available_at <= CURRENT_TIMESTAMP(3)
  AND delivery_attempt < #{maxAttempts}
  AND gmt_create > #{retryWindowStart}

UPDATE agent_conversation_turn
SET delivery_status = #{status},
    delivery_error = #{error},
    delivery_available_at = #{availableAt}
WHERE id = #{id}
  AND direction = 'OUT'
  AND delivery_status = 'SENDING'
  AND delivery_attempt = #{attempt}
